
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

// Use Optimize for somewhat similar sequences @ https://blast.ncbi.nlm.nih.gov/Blast.cgi?PROGRAM=blastn&BLAST_SPEC=GeoBlast&PAGE_TYPE=BlastSearch

val genomeSnippet = ""
val targetGenome = ""
val testAgainst = ""

class SequenceAlignmentTest {

    @Test
    fun testGap() {
        val result = align("AGT", "AT")

        assertEquals("AGT", result.first)
        assertEquals("A-T", result.second)
    }

    @Test
    fun testExactMatch() {
        val result = align("ACGT", "ACGT")

        assertEquals("ACGT", result.first)
        assertEquals("ACGT", result.second)
    }

    @Test
    fun testEmptySequence() {
        val result = align("ACGT", "")

        assertEquals("ACGT", result.first)
        assertEquals("--", result.second)
    }

    @Test
    fun testSalmonella(){
        val result = align(genomeSnippet, testAgainst)

        println(result.first)
        println(result.second)

        assertEquals(result.first.length, result.second.length)

    }

}

